import java.util.Arrays;
import java.util.Comparator;
import java.util.Optional;

public class Example {
    public Optional<String> findSmallestButKeepSorted(String[] items) {
        // Should not match if other operations follow sorted() besides findFirst()
        return Arrays.stream(items)
                     .sorted(Comparator.comparingInt(String::length))
                     .skip(1) // additional operation
                     .findFirst();
    }

    public Optional<String> findLargest(String[] items) {
        // Should not match if using max()
        return Arrays.stream(items)
                     .max(Comparator.comparingInt(String::length));
    }

    public Optional<String> findFirstElement(String[] items) {
        // Should not match if no sorting is involved
        return Arrays.stream(items).findFirst();
    }
}
